UPDATE articulos a SET contenido=(SELECT string_agg(coalesce(v.texto,substring(a.contenido from v.inicio for v.largo)),'' ORDER BY v.orden) FROM (VALUES (0, 1, 34, NULL::text),(1,0,0,E'<thead><tr><th scope="col">Condición de aceptación del sistema o componente mecánico</th><th scope="col">Cumple</th><th scope="col">No cumple</th><th scope="col">N/A*</th></tr></thead>'),(2, 35, 7, NULL::text),(3, 163, 23, NULL::text),(4,0,0,E'<td colspan="3">'),(5, 190, 444, NULL::text)) v(orden,inicio,largo,texto)) WHERE a.id='a0449e12-b510-53cb-82fb-2c1fece27861' AND md5(a.contenido)='5bd5b3ca1836211a58ddce751c0a4d81' RETURNING a.id,md5(a.contenido) hash;